package org.basaltmc.auth

import org.basaltmc.common.hash.Md5
import kotlin.uuid.ExperimentalUuidApi
import kotlin.uuid.Uuid

/**
 * Mirrors vanilla's `net.minecraft.core.UUIDUtil.createOfflinePlayerUUID`: a version-3
 * (name-based, MD5) UUID of `"OfflinePlayer:" + name` in UTF-8, matching Java's
 * `UUID.nameUUIDFromBytes` (RFC 4122 §4.3) bit for bit. Golden vectors were generated by running
 * the real `UUID.nameUUIDFromBytes` on the JDK, not derived from memory.
 */
@OptIn(ExperimentalUuidApi::class)
public object OfflineUuid {
    public fun forUsername(name: String): Uuid {
        val digest = Md5.digest(("OfflinePlayer:$name").encodeToByteArray()).copyOf()
        // RFC 4122: set the version (3) and variant (RFC 4122, "10xx") bits over the raw MD5 digest.
        digest[6] = ((digest[6].toInt() and 0x0F) or 0x30).toByte()
        digest[8] = ((digest[8].toInt() and 0x3F) or 0x80).toByte()

        var msb = 0L
        for (i in 0 until 8) msb = (msb shl 8) or (digest[i].toLong() and 0xFFL)
        var lsb = 0L
        for (i in 8 until 16) lsb = (lsb shl 8) or (digest[i].toLong() and 0xFFL)
        return Uuid.fromLongs(msb, lsb)
    }
}
